// The /hf page's words: its own twenty-language table, its tour, and the class
// that reads them. The page deliberately does not load the shared dictionary
// (static/js/i18n/*): it needs a few hundred words, not the board's thousands,
// and it reads the same language key the rest of the app writes.
// Guards: scripts/check_i18n_calls.py (every word the page asks for is defined, and all
// twenty languages carry the same keys and placeholders) and
// scripts/check_tour_i18n.py (the tour and the language mirror below).

//: The language every page of the app reads and the pickers write.
export const LANG_KEY = "llamacppAdminLang";

// Mirrors LANGS in i18n-data.js (kept here so the page stays independent of the
// big dictionary); scripts/check_tour_i18n.py enforces the mirror.
export const HF_LANGS = [
  ["en", "☕ English"], ["zh", "🐼 中文"], ["hi", "🪷 हिन्दी"], ["es", "🥘 Español"],
  ["fr", "🥐 Français"], ["ar", "🕌 العربية"], ["bn", "🐅 বাংলা"], ["pt", "⚽ Português"],
  ["ru", "🪆 Русский"], ["ja", "🗻 日本語"], ["de", "🥨 Deutsch"], ["id", "🦎 Bahasa Indonesia"],
  ["ur", "🌙 اردو"], ["tr", "🧿 Türkçe"], ["ko", "🥋 한국어"], ["vi", "🛵 Tiếng Việt"],
  ["it", "🍕 Italiano"], ["te", "🪔 తెలుగు"], ["mr", "🥭 मराठी"], ["ta", "🐘 தமிழ்"],
];

